{
  "definition_of_done": [
    "A workgroup with no projects shows a \"No projects yet\" card in the projects table.",
    "A filter that matches nothing shows \"No results\", not the empty card."
  ],
  "qa_plan": [
    { "id": "QA-1", "user_sees": "With no projects, the table shows \"No projects yet\"", "reads": ["visible_text"] },
    { "id": "QA-2", "user_sees": "A filter with no match shows \"No results\", not the empty card", "reads": ["visible_text"] },
    { "id": "QA-3", "user_sees": "With 1,000 projects, the first page shows 25 rows", "reads": ["row_count"], "edge_case": true }
  ],
  "files": ["frontend/src/components/ProjectsTable/ProjectsTable.tsx", "frontend/src/components/ProjectsTable/EmptyCard.tsx"],
  "estimate_minutes": 70,
  "risk": "low"
}

import { z } from "zod";

export const QACheck = z.object({
  id: z.string().regex(/^QA-\d$/),
  user_sees: z.string(),
  reads: z.array(z.enum(["test_id", "aria_role", "visible_text", "row_count"])).min(1),
  edge_case: z.boolean().default(false),
});

export const Plan = z.object({
  definition_of_done: z.array(z.string()).min(1).max(5),
  qa_plan: z.array(QACheck).min(3).max(5),
  files: z.array(z.string()),
  estimate_minutes: z.number().int(),
  risk: z.enum(["low", "med", "high"]),
}).superRefine((p, ctx) => {
  if (!p.qa_plan.some((c) => c.edge_case)) {
    ctx.addIssue({ code: "custom", path: ["qa_plan"], message: "add at least one edge case check" });
  }
});
export type Plan = z.infer<typeof Plan>;

export const acceptPlan = (output: unknown): { plan: Plan } | { fix: string } => {
  const parsed = Plan.safeParse(output);
  if (parsed.success) return { plan: parsed.data };
  return { fix: parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`).join("\n") };
};

